mapper.select:
Select A.대표번호 as topNo -- 대표번호 ,B.대표 as topNoNm ,A.개인번호 as nmNo -- 개인번호 ,A.순서 as seqNo -- 순서 ,A.성명 as nmName -- 성명 ,A.가족관계 as familyRelation -- 가족관계 ,(Select 코드명 from 코드 where 코드 = A.가족관계 and 구분 = '02') as familyRelationNm ,A.생년월일 as birthDate -- 생년월일 ,A.세례일 as baptismDate -- 세례일 ,A.사랑방 as loveGroup -- 사랑방 ,(Select 코드명 from 코드 where 코드 = A.사랑방 and 구분 = '01') as loveGroupNm ,A.핸드폰 as hndTell -- 핸드폰 ,A.직분 as duty -- 직분 ,(Select 코드명 from 코드 where 코드 = A.직분 and 구분 = '03') as dutyNm ,A.전화 as tell -- 전화 ,A.메일 as email -- 메일 ,A.주소 as addr -- 주소 ,A.잔여주소 as addrDu -- 잔여주소 ,A.사용여부 as userYn -- 사용여부 ,A.등록일 as regDate -- 등록일 ,A.수정일 as upDate -- 수정일 ,A.직업 as work -- 직업 ,A.설명 as cnte -- 설명 ,A.우편번호 as post -- 우편번호 ,A.경제활동 as workActiveGb -- 경제활동 ,A.순번그룹 as seqGroup -- 순번그룹 ,A.순번번호 as codeSeqNo -- 순번번호 ,A.인터넷통신 as web -- 인터넷통신 From 가족구성원 A left Outer Join 가족 B on A.대표번호 = B.대표번호
where A.대표번호 = #{topNo}
order by A.순서

mapper.update:
delete from 가족구성원 
where 대표번호 = #{topNo}
  and 개인번호	 = #{nmNo}	-- 개인번호
